-- Keep the old algorithm available only inside the trusted source boundary.
alter function public.measure_sitefit_catchment(uuid,uuid,uuid,uuid,uuid,jsonb) rename to measure_sitefit_catchment_bng2;
revoke all on function public.measure_sitefit_catchment_bng2(uuid,uuid,uuid,uuid,uuid,jsonb) from public,anon,authenticated;
create function public.measure_sitefit_catchment(p_geography_release_id uuid,p_native_release_id uuid,p_census_release_id uuid,p_income_release_id uuid,p_bres_release_id uuid,p_geometry jsonb)
returns jsonb language plpgsql stable security invoker set search_path='' as $fn$
declare r jsonb;shape gis.geometry;outside_area double precision;begin
 r:=public.measure_sitefit_catchment_bng2(p_geography_release_id,p_native_release_id,p_census_release_id,p_income_release_id,p_bres_release_id,p_geometry);
 shape:=source_data.checked_enrichment_polygon(p_geometry);
 outside_area:=gis.st_area(gis.st_transform(gis.st_difference(shape,source_data.sitefit_london_extent_2021()),27700));
 return r||jsonb_build_object('schemaVersion',3,'methodVersion','area-uniform-bng3','coverageExtent',jsonb_build_object('version','ons-london-bfe-2021-v1','sha256','955fbae44301c2191d0c20f1fdfefb53c07a953a19b484f99003b0f15cd135cd','outsideAreaM2',outside_area,'clippedGapAreaM2',greatest(0,(r->>'catchmentAreaM2')::double precision-(r->>'londonCoveredAreaM2')::double precision)),
 'limitations',(r->'limitations')||jsonb_build_array('Administrative London coverage is checked against ONS December 2021 BFE. Population is allocated only over the retained BFC Census footprint; coastal-clipped gaps do not establish missing Census cells.'));
end $fn$;
revoke all on function public.measure_sitefit_catchment(uuid,uuid,uuid,uuid,uuid,jsonb) from public,anon,authenticated;
grant execute on function public.measure_sitefit_catchment(uuid,uuid,uuid,uuid,uuid,jsonb) to service_role;
-- Read-only certificate for an owned immutable Ready edition; no provider calls.
create function public.read_sitefit_report_extent(p_owner uuid,p_report uuid) returns jsonb language plpgsql stable security definer set search_path='' as $fn$
declare r public.reports;w public.data_snapshots;c public.data_snapshots;parts jsonb;begin
 select q.* into r from public.reports q join public.analyses a on a.id=q.analysis_id where q.id=p_report and a.owner_id=p_owner and q.status='ready' and q.tier='free';
 if not found then raise exception 'extent_report_denied' using errcode='42501';end if;
 select * into w from public.data_snapshots where analysis_id=r.analysis_id and input_id=r.input_id and source='geoapify-walking' and r.provenance->'sourceSnapshotIds' ? id::text;
 select * into c from public.data_snapshots where analysis_id=r.analysis_id and input_id=r.input_id and source='ons-catchments' and r.provenance->'sourceSnapshotIds' ? id::text;
 if w.id is null or c.id is null or w.normalised_data->>'kind'<>'walking_geometry' or c.normalised_data#>>'{parent,snapshotId}'<>w.id::text or c.normalised_data#>>'{parent,checksum}'<>w.provider_metadata#>>'{meta,checksum}' then raise exception 'extent_source_binding';end if;
 select jsonb_agg(jsonb_build_object('seconds',p->'seconds','outsideAreaM2',gis.st_area(gis.st_transform(gis.st_difference(source_data.checked_enrichment_polygon(p->'geometry'),source_data.sitefit_london_extent_2021()),27700))) order by (p->>'seconds')::integer) into parts from jsonb_array_elements(w.normalised_data#>'{walking,polygons}') p;
 return jsonb_build_object('walkingId',w.id,'populationId',c.id,'walkingChecksum',w.provider_metadata#>>'{meta,checksum}','populationChecksum',c.provider_metadata#>>'{meta,checksum}','parts',parts);
end $fn$;
